-- 13A PRECHECK: ONE read-only statement (catalog + aggregate counts; NEVER row contents) to run against prod BEFORE any 13A pack
-- 13A ORDERS HARDENING: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/13a-orders-hardening/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL without Joe's relayed yes + a Sentinel pass + a backup. Apply AFTER 12A (12A's drift guard expects the original event_orders ACL/policies). See README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Captures: qr_token column DEFAULT expression, every event_orders policy text, table ACL + column ACLs + per-role privileges, triggers/indexes/constraints, role flags, the FULL bodies of fulfill_ticket_order / refund_ticket_order / get_ticket (byte-compare against baseline/PROD-FACTS-13A.md), every other object that reads event_orders (policies on other tables, views, functions) so the anon-SELECT question can be answered, and aggregate counts.
-- Compare: the packs' drift guard expects the state in baseline/PROD-FACTS-13A.md + 12a facts. If any row here differs, STOP and re-review.
WITH items(k, v) AS (
  SELECT 'meta.server_version', current_setting('server_version') || ' as ' || current_user
  UNION ALL SELECT 'roles.flags', (SELECT string_agg(rolname || ':bypassrls=' || rolbypassrls || ',super=' || rolsuper, ' | ' ORDER BY rolname) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','postgres','authenticator'))
  UNION ALL SELECT 'orders.relkind_rls_force_owner', (SELECT c.relkind::text || '/' || c.relrowsecurity || '/' || c.relforcerowsecurity || '/' || pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass)
  UNION ALL SELECT 'orders.columns:' || a.attnum || ':' || a.attname, format_type(a.atttypid, a.atttypmod) || CASE WHEN a.attnotnull THEN ' NOT NULL' ELSE '' END || coalesce(' DEFAULT ' || pg_get_expr(d.adbin, d.adrelid), '') || CASE WHEN a.attidentity <> '' THEN ' IDENTITY=' || a.attidentity::text ELSE '' END FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.attrelid = 'public.event_orders'::regclass AND a.attnum > 0 AND NOT a.attisdropped
  UNION ALL SELECT 'orders.qr_token_default', coalesce((SELECT pg_get_expr(d.adbin, d.adrelid) FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum WHERE d.adrelid = 'public.event_orders'::regclass AND a.attname = 'qr_token'), '(NO DEFAULT)')
  UNION ALL SELECT 'orders.acl_raw_and_sorted', (SELECT coalesce(c.relacl::text,'(default)') || '  SORTED ' || coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass)
  UNION ALL SELECT 'orders.column_acls:' || a.attname, a.attacl::text FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attacl IS NOT NULL
  UNION ALL SELECT 'orders.column_acls.count', (SELECT count(*)::text FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attacl IS NOT NULL)
  UNION ALL SELECT 'orders.privs:' || r, (SELECT string_agg(p, ',' ORDER BY p) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN']) p WHERE has_table_privilege(r, 'public.event_orders'::regclass, p)) FROM unnest(ARRAY['anon','authenticated','service_role','postgres']) r
  UNION ALL SELECT 'orders.policy:' || p.policyname, 'cmd=' || p.cmd || ' roles=' || array_to_string(p.roles, ',') || ' ' || p.permissive || ' USING ' || coalesce(p.qual, '(null)') || ' WITH CHECK ' || coalesce(p.with_check, '(null)') FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'event_orders'
  UNION ALL SELECT 'orders.indexes:' || i.indexname, i.indexdef FROM pg_indexes i WHERE i.schemaname = 'public' AND i.tablename = 'event_orders'
  UNION ALL SELECT 'orders.constraints:' || c.conname, pg_get_constraintdef(c.oid) FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass
  UNION ALL SELECT 'orders.triggers:' || t.tgname, pg_get_triggerdef(t.oid) FROM pg_trigger t WHERE t.tgrelid = 'public.event_orders'::regclass AND NOT t.tgisinternal
  UNION ALL SELECT 'orders.triggers.count', (SELECT count(*)::text FROM pg_trigger t WHERE t.tgrelid = 'public.event_orders'::regclass AND NOT t.tgisinternal)
  UNION ALL SELECT 'orders.id_sequence_acl', coalesce((SELECT s.relacl::text FROM pg_class s WHERE s.oid = pg_get_serial_sequence('public.event_orders','id')::regclass), '(identity/none or default)')
  UNION ALL SELECT 'orders.default_acls_public_schema', coalesce((SELECT string_agg(pg_get_userbyid(d.defaclrole) || ':' || d.defaclobjtype::text || ':' || d.defaclacl::text, ' | ') FROM pg_default_acl d WHERE d.defaclnamespace IN (0, to_regnamespace('public')::oid)), '(none)')
  UNION ALL SELECT 'fulfill.def:' || p.oid::regprocedure::text, pg_get_functiondef(p.oid) FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'fulfill_ticket_order'
  UNION ALL SELECT 'fulfill.prosrc_md5:' || p.oid::regprocedure::text, md5(p.prosrc) || ' ws_md5=' || md5(regexp_replace(p.prosrc, '\s+', '', 'g')) FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'fulfill_ticket_order'
  UNION ALL SELECT 'fulfill.attrs:' || p.oid::regprocedure::text, 'secdef=' || p.prosecdef || ' owner=' || pg_get_userbyid(p.proowner) || ' config=' || coalesce(p.proconfig::text,'(none)') || ' lang=' || (SELECT lanname FROM pg_language WHERE oid = p.prolang) || ' ret=' || p.prorettype::regtype || ' args=' || pg_get_function_identity_arguments(p.oid) || ' comment=' || coalesce(obj_description(p.oid,'pg_proc'),'none') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'fulfill_ticket_order'
  UNION ALL SELECT 'fulfill.acl_raw_and_sorted:' || p.oid::regprocedure::text, coalesce(p.proacl::text,'(default)') || '  SORTED ' || coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'fulfill_ticket_order'
  UNION ALL SELECT 'fulfill.exec:' || p.oid::regprocedure::text, 'anon=' || has_function_privilege('anon', p.oid, 'EXECUTE') || ' authenticated=' || has_function_privilege('authenticated', p.oid, 'EXECUTE') || ' service_role=' || has_function_privilege('service_role', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'fulfill_ticket_order'
  UNION ALL SELECT 'fulfill.dependents:' || p.oid::regprocedure::text, (SELECT count(*) FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n')::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'fulfill_ticket_order'
  UNION ALL SELECT 'refund.def:' || p.oid::regprocedure::text, pg_get_functiondef(p.oid) FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'refund_ticket_order'
  UNION ALL SELECT 'refund.prosrc_md5:' || p.oid::regprocedure::text, md5(p.prosrc) || ' ws_md5=' || md5(regexp_replace(p.prosrc, '\s+', '', 'g')) FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'refund_ticket_order'
  UNION ALL SELECT 'refund.attrs:' || p.oid::regprocedure::text, 'secdef=' || p.prosecdef || ' owner=' || pg_get_userbyid(p.proowner) || ' config=' || coalesce(p.proconfig::text,'(none)') || ' lang=' || (SELECT lanname FROM pg_language WHERE oid = p.prolang) || ' ret=' || p.prorettype::regtype || ' args=' || pg_get_function_identity_arguments(p.oid) || ' comment=' || coalesce(obj_description(p.oid,'pg_proc'),'none') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'refund_ticket_order'
  UNION ALL SELECT 'refund.acl_raw_and_sorted:' || p.oid::regprocedure::text, coalesce(p.proacl::text,'(default)') || '  SORTED ' || coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'refund_ticket_order'
  UNION ALL SELECT 'refund.exec:' || p.oid::regprocedure::text, 'anon=' || has_function_privilege('anon', p.oid, 'EXECUTE') || ' authenticated=' || has_function_privilege('authenticated', p.oid, 'EXECUTE') || ' service_role=' || has_function_privilege('service_role', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'refund_ticket_order'
  UNION ALL SELECT 'refund.dependents:' || p.oid::regprocedure::text, (SELECT count(*) FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n')::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'refund_ticket_order'
  UNION ALL SELECT 'get_ticket.def:' || p.oid::regprocedure::text, pg_get_functiondef(p.oid) FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'
  UNION ALL SELECT 'get_ticket.prosrc_md5:' || p.oid::regprocedure::text, md5(p.prosrc) || ' ws_md5=' || md5(regexp_replace(p.prosrc, '\s+', '', 'g')) FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'
  UNION ALL SELECT 'get_ticket.attrs:' || p.oid::regprocedure::text, 'secdef=' || p.prosecdef || ' owner=' || pg_get_userbyid(p.proowner) || ' config=' || coalesce(p.proconfig::text,'(none)') || ' lang=' || (SELECT lanname FROM pg_language WHERE oid = p.prolang) || ' ret=' || p.prorettype::regtype || ' args=' || pg_get_function_identity_arguments(p.oid) || ' comment=' || coalesce(obj_description(p.oid,'pg_proc'),'none') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'
  UNION ALL SELECT 'get_ticket.acl_raw_and_sorted:' || p.oid::regprocedure::text, coalesce(p.proacl::text,'(default)') || '  SORTED ' || coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'
  UNION ALL SELECT 'get_ticket.exec:' || p.oid::regprocedure::text, 'anon=' || has_function_privilege('anon', p.oid, 'EXECUTE') || ' authenticated=' || has_function_privilege('authenticated', p.oid, 'EXECUTE') || ' service_role=' || has_function_privilege('service_role', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'
  UNION ALL SELECT 'get_ticket.dependents:' || p.oid::regprocedure::text, (SELECT count(*) FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n')::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'get_ticket'
  UNION ALL SELECT 'get_ticket.helper_name_free', (SELECT count(*)::text FROM pg_proc p WHERE p.proname = 'get_ticket__orig_13a')
  UNION ALL SELECT 'readers.functions_mentioning_event_orders:' || p.oid::regprocedure::text, 'secdef=' || p.prosecdef || ' config=' || coalesce(p.proconfig::text,'(none)') || ' exec anon=' || has_function_privilege('anon', p.oid, 'EXECUTE') || ' authenticated=' || has_function_privilege('authenticated', p.oid, 'EXECUTE') || ' md5=' || md5(p.prosrc) FROM pg_proc p WHERE p.pronamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog','information_schema')) AND p.prosrc ~* 'event_orders'
  UNION ALL SELECT 'readers.policies_on_other_tables_mentioning_event_orders:' || p.schemaname || '.' || p.tablename || '.' || p.policyname, 'cmd=' || p.cmd || ' roles=' || array_to_string(p.roles, ',') || ' ' || coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'') FROM pg_policies p WHERE (coalesce(p.qual,'') || coalesce(p.with_check,'')) ~* 'event_orders' AND NOT (p.schemaname = 'public' AND p.tablename = 'event_orders')
  UNION ALL SELECT 'readers.views_mentioning_event_orders:' || n.nspname || '.' || c.relname, c.relkind::text FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.relkind IN ('v','m') AND pg_get_viewdef(c.oid) ~* 'event_orders'
  UNION ALL SELECT 'readers.dependents_via_pg_depend:' || coalesce(rc.relname, '?'), d.deptype::text FROM pg_depend d JOIN pg_rewrite rw ON rw.oid = d.objid AND d.classid = 'pg_rewrite'::regclass JOIN pg_class rc ON rc.oid = rw.ev_class WHERE d.refclassid = 'pg_class'::regclass AND d.refobjid = 'public.event_orders'::regclass
  UNION ALL SELECT 'agg.orders_by_status:' || coalesce(o.status,'(null)'), count(*)::text FROM public.event_orders o GROUP BY o.status
  UNION ALL SELECT 'agg.orders_total_and_checked_in', count(*)::text || ' total, ' || count(*) FILTER (WHERE checked_in_at IS NOT NULL)::text || ' checked in, ' || count(*) FILTER (WHERE qr_token IS NULL)::text || ' without qr_token, ' || count(*) FILTER (WHERE stripe_session_id IS NULL)::text || ' without stripe_session_id' FROM public.event_orders
  UNION ALL SELECT 'agg.qr_token_duplicate_surplus_rows', coalesce((SELECT sum(c - 1)::text FROM (SELECT count(*) c FROM public.event_orders WHERE qr_token IS NOT NULL GROUP BY qr_token HAVING count(*) > 1) z), '0')
  UNION ALL SELECT 'agg.orders_without_stripe_session_by_status:' || coalesce(o.status,'(null)'), count(*)::text FROM public.event_orders o WHERE o.stripe_session_id IS NULL GROUP BY o.status
)
SELECT k AS name, v AS value FROM items ORDER BY k;
